input.content:
:root {
  --ink: #07060d;
  --ink-2: #0d0a16;
  --panel: rgba(13, 10, 21, 0.82);
  --bone: #f3ead9;
  --bone-dim: #bbae9b;
  --blood: #e3425f;
  --blood-hot: #ff5d78;
  --blood-deep: #8f1734;
  --gold: #d8ad6a;
  --gold-pale: #f6dca7;
  --mist: #8d93b2;
  --line: rgba(226, 190, 149, 0.18);
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, "Iowan Old Style", "Times New Roman", serif;
  --sans: "Avenir Next", Avenir, "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

button { font: inherit; color: inherit; }
kbd {
  display: inline-block;
  min-width: 22px;
  padding: 2px 5px 1px;
  border: 1px solid rgba(243, 234, 217, 0.25);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--bone-dim);
  font-family: var(--sans);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-align: center;
  box-shadow: inset 0 -1px 0 rgba(255,255,255,.06);
}
.hidden { display: none !important; }

#app {
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 100%;
  height: 100svh;
  overflow: hidden;
  background: var(--ink);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.grain {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  opacity: 0.16;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.42'/%3E%3C/svg%3E");
  background-size: 240px 240px;
}
.vignette {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 47%, transparent 38%, rgba(4, 3, 8, 0.5) 78%, rgba(3, 2, 7, 0.95) 120%),
    linear-gradient(to bottom, rgba(4, 3, 8, 0.46), transparent 18%, transparent 77%, rgba(4, 3, 8, 0.74));
}
#low-horde {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(117, 0, 24, 0.4) 90%, rgba(80, 0, 16, 0.66));
  transition: opacity .35s ease;
  animation: lowPulse 1.1s ease-in-out infinite alternate;
}
#low-horde.on { opacity: 1; }
@keyframes lowPulse { from { filter: brightness(.85); } to { filter: brightness(1.3); } }

/* ---------- Shared type ---------- */
.eyebrow {
  display: block;
  font-family: var(--sans);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .26em;
  color: rgba(243, 234, 217, .55);
  text-transform: uppercase;
}
.level-kicker {
  color: var(--blood);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .36em;
  text-transform: uppercase;
}

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: max(18px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(20px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  animation: hudIn .7s ease both;
}
@keyframes hudIn { from { opacity: 0; } to { opacity: 1; } }
.hud-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; }
.glass {
  position: relative;
  background:
    linear-gradient(135deg, rgba(255,255,255,.045), transparent 42%),
    var(--panel);
  border: 1px solid var(--line);
  box-shadow: 0 12px 40px rgba(0,0,0,.28), inset 0 1px 0 rgba(255,255,255,.035);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.glass::before, .glass::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  pointer-events: none;
  border-color: rgba(227, 66, 95, .55);
  border-style: solid;
}
.glass::before { top: -1px; left: -1px; border-width: 1px 0 0 1px; }
.glass::after { bottom: -1px; right: -1px; border-width: 0 1px 1px 0; }

.horde-panel {
  display: flex;
  align-items: center;
  gap: 13px;
  width: 232px;
  padding: 11px 15px 10px 12px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
}
.horde-icon {
  width: 44px;
  height: 44px;
  color: var(--blood);
  filter: drop-shadow(0 0 9px rgba(227, 66, 95, .45));
  flex: 0 0 auto;
}
.horde-icon svg { display: block; width: 100%; height: 100%; }
.horde-text { flex: 1; min-width: 0; }
.horde-number {
  margin-top: 1px;
  font-family: var(--serif);
  font-size: 25px;
  line-height: .9;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.horde-number strong { font-weight: 700; color: #fff5e4; }
.horde-number span { font-family: var(--sans); font-size: 10px; font-weight: 600; letter-spacing: .05em; color: rgba(243,234,217,.42); }
.horde-number b { font-weight: 600; }
.meter { height: 3px; margin-top: 7px; overflow: hidden; background: rgba(255,255,255,.09); border-radius: 3px; }
.meter i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, var(--blood-deep), var(--blood-hot)); box-shadow: 0 0 10px var(--blood); transition: width .2s ease; }

.timer-panel { text-align: center; padding-top: 5px; min-width: 138px; }
.timer-panel .eyebrow { color: rgba(216, 173, 106, .78); letter-spacing: .32em; }
#timer {
  font-family: var(--serif);
  font-size: 36px;
  line-height: .95;
  margin-top: 3px;
  letter-spacing: .03em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 22px rgba(0,0,0,.75);
}
.timer-sub { display: block; font-size: 7px; letter-spacing: .31em; color: rgba(243,234,217,.38); margin-top: 3px; }
.timer-panel.urgent #timer { color: var(--blood-hot); animation: urgent 1s ease-in-out infinite alternate; }
@keyframes urgent { to { text-shadow: 0 0 26px rgba(255, 72, 100, .75); } }

.score-panel {
  display: flex;
  align-items: center;
  height: 56px;
  padding: 0 9px 0 7px;
  clip-path: polygon(12px 0, 100% 0, 100% 100%, 0 100%, 0 12px);
}
.icon-btn {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: rgba(243,234,217,.5);
  cursor: pointer;
  display: grid;
  place-items: center;
  pointer-events: auto;
  transition: .2s ease;
}
.icon-btn:hover { color: var(--bone); background: rgba(255,255,255,.06); }
.icon-btn svg { width: 16px; height: 16px; }
.icon-btn .sound-off { display: none; }
.icon-btn.muted .sound-on { display: none; }
.icon-btn.muted .sound-off { display: block; }
.kill-stat { min-width: 76px; padding: 0 7px 0 12px; border-left: 1px solid rgba(255,255,255,.08); text-align: right; }
.kill-stat strong { display: block; font-family: var(--serif); font-size: 22px; line-height: 1; color: var(--gold-pale); font-variant-numeric: tabular-nums; }

.hud-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
.xp-panel { width: min(380px, 40vw); pointer-events: none; }
.xp-head { display: flex; align-items: flex-end; justify-content: space-between; font-size: 8px; font-weight: 700; letter-spacing: .19em; color: rgba(243,234,217,.48); margin-bottom: 6px; }
.xp-head b { color: var(--gold-pale); font-size: 13px; }
.xp-track { height: 4px; background: rgba(255,255,255,.08); overflow: hidden; border-radius: 3px; box-shadow: 0 0 0 1px rgba(255,255,255,.03); }
.xp-track i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #7c4fbd, #cda2ff); box-shadow: 0 0 12px rgba(161, 111, 255, .62); transition: width .3s ease; }
.objective { display: flex; align-items: center; gap: 8px; margin-top: 9px; font-size: 10px; letter-spacing: .04em; color: rgba(243,234,217,.52); }
.obj-dot { width: 4px; height: 4px; transform: rotate(45deg); background: var(--blood); box-shadow: 0 0 8px var(--blood); flex: 0 0 auto; }

.ability-wrap { position: relative; pointer-events: none; text-align: right; }
.ability {
  position: relative;
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 180px;
  padding: 8px 14px 8px 9px;
  color: var(--bone);
  background: rgba(13, 10, 21, .82);
  border: 1px solid rgba(227,66,95,.35);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  cursor: pointer;
  transition: .2s ease;
  backdrop-filter: blur(10px);
}
.ability:hover { border-color: rgba(255,93,120,.7); background: rgba(28,10,20,.92); }
.ability-ring {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(227,66,95,.55);
  background: radial-gradient(circle, rgba(227,66,95,.26), rgba(227,66,95,.02) 68%);
  color: var(--blood-hot);
  filter: drop-shadow(0 0 7px rgba(227,66,95,.45));
}
.ability-ring svg { width: 23px; height: 23px; }
.ability-copy { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.ability-copy b { font-size: 9px; letter-spacing: .21em; }
.ability-copy small { font-size: 7px; letter-spacing: .2em; color: rgba(243,234,217,.38); }
.ability-cd { margin-top: 5px; font-size: 7px; font-weight: 800; letter-spacing: .27em; color: var(--blood-hot); }
.ability.cooling .ability-ring { color: rgba(243,234,217,.3); border-color: rgba(255,255,255,.14); background: rgba(255,255,255,.03); filter: none; }
.ability.cooling .ability-cd { color: rgba(243,234,217,.38); }
.mobile-hint { display: none; }
#joystick {
  display: none;
  position: absolute;
  z-index: 12;
  width: 104px;
  height: 104px;
  margin: -52px 0 0 -52px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(227,66,95,.1), rgba(7,6,13,.3));
  pointer-events: none;
  backdrop-filter: blur(3px);
}
#joystick span {
  position: absolute;
  left: 50%; top: 50%;
  width: 38px; height: 38px;
  margin: -19px;
  border-radius: 50%;
  border: 1px solid rgba(255,93,120,.7);
  background: radial-gradient(circle, rgba(227,66,95,.65), rgba(100,18,41,.5));
  box-shadow: 0 0 20px rgba(227,66,95,.35);
}
#joystick.on { display: block; }

/* ---------- Title ---------- */
.screen { position: absolute; inset: 0; z-index: 20; }
.title-screen {
  display: flex;
  align-items: center;
  padding: clamp(22px, 5vw, 74px);
  padding-top: max(26px, env(safe-area-inset-top));
  padding-bottom: max(38px, env(safe-area-inset-bottom));
  overflow: hidden;
}
.title-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(5,4,10,.97) 0%, rgba(5,4,10,.88) 29%, rgba(5,4,10,.56) 49%, rgba(5,4,10,.1) 76%, rgba(5,4,10,.2) 100%),
    linear-gradient(0deg, rgba(5,4,10,.78), transparent 30%, transparent 72%, rgba(5,4,10,.45));
}
.title-content {
  position: relative;
  z-index: 2;
  width: min(650px, 55vw);
  animation: titleIn 1.1s cubic-bezier(.2,.8,.2,1) both .15s;
}
@keyframes titleIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.title-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(100%, 470px);
  color: rgba(216,173,106,.75);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .4em;
  white-space: nowrap;
}
.title-kicker span { width: 28px; height: 1px; background: linear-gradient(90deg, transparent, rgba(216,173,106,.5)); }
.title-kicker span:last-child { background: linear-gradient(90deg, rgba(216,173,106,.5), transparent); }
.game-title {
  position: relative;
  margin: 6px 0 0 -8px;
  font-family: var(--serif);
  font-size: clamp(106px, 14.5vw, 190px);
  line-height: .76;
  letter-spacing: -.035em;
  font-weight: 700;
  color: #f7e7cc;
  background: linear-gradient(180deg, #fff7e6 0%, #e7c9a0 43%, #b95b62 68%, #7e1b34 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 5px 0 rgba(26, 6, 14, .72)) drop-shadow(0 12px 30px rgba(155, 24, 54, .22));
}
.game-title span { display: inline-block; }
.title-h { transform: rotate(-1deg); }
.title-o { transform: translateY(2px) rotate(.6deg); }
.title-r { transform: rotate(-.7deg); }
.title-d { transform: translateY(1px) rotate(.4deg); }
.title-e { transform: rotate(-.4deg); }
.title-drip {
  position: absolute;
  top: 78%;
  width: 3px;
  border-radius: 0 0 50% 50%;
  background: linear-gradient(to bottom, #8e1d38, #520c20);
  opacity: .8;
}
.drip-a { left: 14%; height: 22px; }
.drip-b { left: 57%; height: 38px; width: 4px; top: 80%; }
.drip-c { left: 82%; height: 14px; }
.title-rule {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(100%, 510px);
  margin: 10px 0 20px;
  color: rgba(243,234,217,.45);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .34em;
}
.title-rule i { height: 1px; flex: 1; background: linear-gradient(90deg, rgba(216,173,106,.34), transparent); }
.title-rule i:last-child { background: linear-gradient(270deg, rgba(216,173,106,.34), transparent); }
.title-hook {
  margin: 0 0 14px;
  font-family: var(--serif);
  font-size: clamp(19px, 1.8vw, 27px);
  line-height: 1.32;
  letter-spacing: .005em;
  color: rgba(243,234,217,.86);
}
.title-hook em { color: var(--blood-hot); font-style: italic; text-shadow: 0 0 24px rgba(227,66,95,.3); }
.title-desc {
  margin: 0 0 24px;
  max-width: 500px;
  font-size: clamp(11px, .92vw, 14px);
  line-height: 1.72;
  color: rgba(243,234,217,.44);
}
.title-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 13px; }
.primary-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 13px;
  width: min(368px, 100%);
  min-height: 64px;
  padding: 10px 14px;
  border: 1px solid rgba(255,117,138,.55);
  background:
    linear-gradient(115deg, rgba(255,255,255,.1), transparent 30%),
    linear-gradient(90deg, #79162e, #a32241 54%, #6f1028);
  color: #fff0dc;
  cursor: pointer;
  clip-path: polygon(13px 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%, 0 13px);
  box-shadow: 0 16px 40px rgba(87, 7, 28, .34), inset 0 1px 0 rgba(255,255,255,.15);
  transition: transform .2s ease, filter .2s ease, box-shadow .2s ease;
  text-align: left;
}
.primary-btn::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(255,232,203,.1);
  pointer-events: none;
}
.primary-btn:hover { transform: translateY(-2px); filter: brightness(1.13); box-shadow: 0 20px 50px rgba(138, 15, 46, .48), inset 0 1px 0 rgba(255,255,255,.18); }
.primary-btn:active { transform: translateY(0); }
.btn-icon { width: 36px; height: 36px; flex: 0 0 auto; color: #ffd9c0; filter: drop-shadow(0 0 12px rgba(255,168,160,.35)); }
.btn-icon svg { width: 100%; height: 100%; }
.primary-btn b { display: block; font-size: 11px; font-weight: 800; letter-spacing: .23em; }
.primary-btn small { display: block; margin-top: 3px; font-size: 7px; letter-spacing: .22em; color: rgba(255,232,203,.52); }
.btn-arrow { margin-left: auto; font-family: var(--serif); font-size: 22px; color: rgba(255,232,203,.55); transition: transform .2s ease; }
.primary-btn:hover .btn-arrow { transform: translateX(4px); color: #fff; }
.title-meta { display: flex; gap: 17px; flex-wrap: wrap; align-items: center; color: rgba(243,234,217,.38); font-size: 8px; letter-spacing: .13em; text-transform: uppercase; }
.title-meta span { display: flex; align-items: center; gap: 6px; }
.title-meta kbd { font-size: 7px; }
.title-record { margin-top: 19px; padding-left: 10px; border-left: 1px solid rgba(227,66,95,.45); font-size: 8px; font-weight: 700; letter-spacing: .18em; color: rgba(216,173,106,.52); text-transform: uppercase; }

.title-side {
  position: absolute;
  z-index: 2;
  right: clamp(24px, 4vw, 70px);
  top: 50%;
  transform: translateY(-46%);
  text-align: right;
  color: rgba(243,234,217,.28);
  animation: titleIn 1.2s ease both .6s;
}
.moon-mark { width: 66px; height: 66px; margin: 0 0 20px auto; position: relative; border: 1px solid rgba(216,173,106,.28); border-radius: 50%; }
.moon-mark::before { content: ""; position: absolute; inset: 10px; border-radius: 50%; background: radial-gradient(circle at 38% 36%, #f6dca7, #b27645 58%, #4f2834 75%); box-shadow: 0 0 38px rgba(216,173,106,.25); }
.moon-mark::after { content: ""; position: absolute; inset: 3px; border: 1px dashed rgba(216,173,106,.24); border-radius: 50%; animation: slowSpin 28s linear infinite; }
.moon-mark span { position: absolute; inset: 18px -4px -4px 18px; background: #07060d; border-radius: 50%; z-index: 1; }
@keyframes slowSpin { to { transform: rotate(360deg); } }
.title-side p { margin: 0; font-family: var(--serif); font-size: 10px; line-height: 1.65; letter-spacing: .19em; }
.title-side small { display: block; margin-top: 6px; font-size: 6px; letter-spacing: .27em; color: rgba(243,234,217,.22); }
.title-footer {
  position: absolute;
  z-index: 3;
  left: clamp(24px, 5vw, 74px);
  right: clamp(24px, 5vw, 74px);
  bottom: max(15px, env(safe-area-inset-bottom));
  display: flex;
  align-items: center;
  gap: 20px;
  color: rgba(243,234,217,.23);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .24em;
}
.footer-bats { flex: 1; overflow: hidden; white-space: nowrap; color: rgba(227,66,95,.4); letter-spacing: .7em; }
.text-btn { border: 0; background: none; color: rgba(243,234,217,.35); font-size: 7px; letter-spacing: .24em; cursor: pointer; padding: 4px 0; }
.text-btn:hover { color: var(--bone); }

/* ---------- Overlay screens ---------- */
.overlay-screen {
  display: grid;
  place-items: center;
  padding: 22px;
  background: radial-gradient(ellipse at center, rgba(10,6,18,.62), rgba(3,2,7,.89) 74%);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: overlayIn .3s ease both;
  overflow-y: auto;
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }
.modal-glow { position: absolute; width: 760px; height: 520px; background: radial-gradient(ellipse, rgba(145,20,53,.22), transparent 65%); pointer-events: none; }
.level-panel { position: relative; z-index: 1; width: min(940px, 95vw); text-align: center; }
.level-panel h2, .small-panel h2, .end-wrap h2 {
  margin: 8px 0 4px;
  font-family: var(--serif);
  font-size: clamp(32px, 4vw, 54px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -.02em;
  color: #f7ead6;
}
.level-sub, .small-copy { margin: 0 0 25px; color: rgba(243,234,217,.4); font-size: 11px; letter-spacing: .04em; }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; width: 100%; }
.card {
  position: relative;
  min-height: 258px;
  padding: 27px 23px 20px;
  border: 1px solid rgba(243,234,217,.14);
  background:
    linear-gradient(145deg, rgba(255,255,255,.045), transparent 44%),
    rgba(12,9,19,.84);
  color: var(--bone);
  cursor: pointer;
  text-align: left;
  overflow: hidden;
  clip-path: polygon(15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%, 0 15px);
  transition: transform .2s ease, border-color .2s ease, background .2s ease;
  animation: cardIn .45s cubic-bezier(.2,.8,.2,1) both;
}
.card:nth-child(2) { animation-delay: .07s; }
.card:nth-child(3) { animation-delay: .14s; }
@keyframes cardIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.card::before { content: ""; position: absolute; inset: 5px; border: 1px solid rgba(255,255,255,.035); pointer-events: none; }
.card::after { content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: 100%; background: linear-gradient(90deg, transparent, var(--blood), transparent); opacity: 0; transition: opacity .2s ease; }
.card:hover { transform: translateY(-4px); border-color: rgba(227,66,95,.55); background: linear-gradient(145deg, rgba(227,66,95,.09), transparent 48%), rgba(17,10,22,.94); }
.card:hover::after { opacity: 1; }
