  H.attract = { t: 0, bats: [], survivors: [] };

  // ---------------------------------------------------------------------------
  // Sound — procedural, no external assets
  // ---------------------------------------------------------------------------
  class Soundscape {
    constructor() {
      this.ctx = null;
      this.master = null;
      this.ambient = null;
      this.enabled = H.store.get('horde.sound', true) !== false;
      this.noise = null;
      this.chime = 0;
    }
    ensure() {
      if (this.ctx) {
        if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
