    g.lineTo(s * 0.34, 0);
    g.closePath();
    g.fill();
    g.strokeStyle = 'rgba(210,190,190,0.07)';
    g.lineWidth = 0.7;
    g.stroke();
    g.strokeStyle = 'rgba(210,190,190,0.11)';
    g.lineWidth = Math.max(1, s * 0.055);
