      const steps = H.randInt(3, 9);
      for (let j = 0; j < steps; j++) {
        a += H.rand(-0.5, 0.5);
        x += Math.cos(a) * H.rand(5, 18);
        y += Math.sin(a) * H.rand(3, 12);
        g.lineTo(x, y);
      }
      g.strokeStyle = `rgba(2,2,6,${H.rand(0.25, 0.6)})`;
      g.lineWidth = H.rand(0.5, 1.4);
