function drawWorldScene(ctx, t) {
  drawCampfire(ctx, H.W * 0.53, H.H * 0.515, 0.72, t);
  drawRifts(ctx);

ctx.save();
let sx = 0, sy = 0;
if (mode !== 'attract') {
  const intensity = state.shake || 0;
  sx = (Math.random() - 0.5) * intensity;
  sy = (Math.random() - 0.5) * intensity;
  const cam = H.camera;
  const z = cam.initialized ? cam.zoom : 1;
  ctx.translate(w / 2 + sx, h / 2 + sy);
  ctx.scale(z, z);
  ctx.translate(-cam.x, -cam.y);
} else {
  ctx.translate(sx, sy);
}
ctx.drawImage(H.backgroundCanvas, 0, 0, w, h);
drawFog(ctx, t);
drawAmbient(ctx, t);

if (mode === 'attract') drawAttract(ctx, t);
else drawWorldScene(ctx, t);

ctx.restore();

