function desiredZoom() {
  if (H.W >= 1280) return 1.42;
  if (H.W >= 900) return 1.28;
  if (H.W >= 640) return 1.14;
  return 1.03;
}

function clampCamera() {
  const cam = H.camera;
  const halfW = H.W / (2 * cam.zoom);
  const halfH = H.H / (2 * cam.zoom);
  cam.x = clamp(cam.x, halfW, H.W - halfW);
  cam.y = clamp(cam.y, halfH, H.H - halfH);
}

H.snapCamera = () => {
  if (!state.horde) return;
  const cam = H.camera;
  cam.zoom = desiredZoom();
  const halfW = H.W / (2 * cam.zoom);
  const halfH = H.H / (2 * cam.zoom);
  cam.x = clamp(state.horde.x + state.horde.vx * 0.1, halfW, H.W - halfW);
  cam.y = clamp(state.horde.y + state.horde.vy * 0.1, halfH, H.H - halfH);
  cam.initialized = true;
};

H.updateCamera = (dt) => {
  if (!state.horde) return;
  const cam = H.camera;
  const zTarget = desiredZoom();
  cam.zoom = lerp(cam.zoom, zTarget, 1 - Math.exp(-dt * 3));
  const halfW = H.W / (2 * cam.zoom);
  const halfH = H.H / (2 * cam.zoom);
  const tx = clamp(state.horde.x + state.horde.vx * 0.13, halfW, H.W - halfW);
  const ty = clamp(state.horde.y + state.horde.vy * 0.13, halfH, H.H - halfH);
  const k = 1 - Math.exp(-dt * 8);
  cam.x = lerp(cam.x, tx, k);
  cam.y = lerp(cam.y, ty, k);
  clampCamera();
};

// ---------------------------------------------------------------------------
// Boot + loop
// ---------------------------------------------------------------------------
let resizeQueued = false;
window.addEventListener('resize', () => {
  if (resizeQueued) return;
  resizeQueued = true;
  requestAnimationFrame(() => {
    resizeQueued = false;
    H.resize();
    if (state.mode !== 'attract') H.snapCamera();
    H.render();
  });
});

