503:     ctx.beginPath(); ctx.arc(-19, -5, 7.5, 0, TAU); ctx.arc(19, -5, 7.5, 0, TAU); ctx.fill();
504:     ctx.strokeStyle = '#a87a41'; ctx.stroke();
505: 
506:     // head/hood
507:     ctx.fillStyle = '#3c2b30';
508:     ctx.beginPath(); ctx.arc(0, -20, 14, 0, TAU); ctx.fill();
509:     ctx.fillStyle = '#e9d8b0';
510:     ctx.beginPath(); ctx.arc(0, -21, 8.4, 0, TAU); ctx.fill();
511:     ctx.fillStyle = '#291d22';
512:     ctx.beginPath(); ctx.arc(0, -23, 6.6, 0.08 * Math.PI, 0.92 * Math.PI); ctx.fill();
513: 
514:     // crown
515:     ctx.strokeStyle = '#ffe4a6'; ctx.fillStyle = '#d8ad6a'; ctx.lineWidth = 1.2;
516:     ctx.beginPath();
517:     ctx.moveTo(-9, -29); ctx.lineTo(-7, -38); ctx.lineTo(-2, -32); ctx.lineTo(2, -40); ctx.lineTo(6, -32); ctx.lineTo(10, -37); ctx.lineTo(10, -28);
518:     ctx.closePath(); ctx.fill(); ctx.stroke();
519: 
520:     // halo
521:     ctx.save();
522:     ctx.globalCompositeOperation = 'lighter';
523:     ctx.strokeStyle = `rgba(255,231,164,${0.58 + Math.sin(t * 2) * 0.17})`;
524:     ctx.lineWidth = 1.5;
525:     ctx.beginPath(); ctx.ellipse(0, -47, 22, 6, 0, 0, TAU); ctx.stroke();
526:     for (let i = 0; i < 8; i++) {
527:       const a = i / 8 * TAU + t * 0.2;
528:       ctx.beginPath();
529:       ctx.moveTo(Math.cos(a) * 22, -47 + Math.sin(a) * 6);
530:       ctx.lineTo(Math.cos(a) * 26, -47 + Math.sin(a) * 7.2);
531:       ctx.stroke();
532:     }
533:     ctx.restore();
534: 
535:     // greatsword
536:     ctx.save();
537:     ctx.translate(23, 2);
538:     ctx.rotate(-0.5 + wind * 2.1);
539:     ctx.strokeStyle = '#f4e8c9'; ctx.lineWidth = 5;
540:     ctx.beginPath(); ctx.moveTo(0, 8); ctx.lineTo(0, -62); ctx.stroke();
541:     ctx.strokeStyle = '#b98945'; ctx.lineWidth = 6;
542:     ctx.beginPath(); ctx.moveTo(-8, 1); ctx.lineTo(8, 1); ctx.stroke();
543:     ctx.fillStyle = '#ffe0a0'; ctx.shadowColor = '#ffd27a'; ctx.shadowBlur = 10;
544:     ctx.beginPath(); ctx.arc(0, 9, 3.2, 0, TAU); ctx.fill();
545:     ctx.shadowBlur = 0;
546:     ctx.restore();
547: 
548:     // casting orb
549:     if (cast) {
550:       ctx.save();
551:       ctx.globalCompositeOperation = 'lighter';
552:       ctx.fillStyle = `rgba(255,222,143,${0.4 + (1 - e.timer / 0.55) * 0.5})`;
553:       ctx.shadowColor = '#ffce72'; ctx.shadowBlur = 25;
554:       ctx.beginPath(); ctx.arc(0, -12, 11 + (1 - e.timer / 0.55) * 10, 0, TAU); ctx.fill();
555:       ctx.restore();
556:     }
557: 
558:     if (e.flash > 0) {
559:       ctx.globalAlpha = e.flash * 0.6;
560:       ctx.fillStyle = '#fff';
561:       ctx.beginPath(); ctx.arc(0, 0, 33, 0, TAU); ctx.fill();
562:     }
563:     ctx.restore();
