569:   function drawRifts(ctx) {
570:     if (!state.rifts.length) return;
571:     ctx.save();
572:     ctx.globalCompositeOperation = 'lighter';
573:     for (const r of state.rifts) {
574:       const p = 1 - r.life / r.max;
575:       const a = (1 - p) * 0.55;
576:       ctx.globalAlpha = a;
577:       ctx.strokeStyle = r.color;
578:       ctx.lineWidth = 1.6;
579:       ctx.beginPath(); ctx.arc(r.x, r.y, r.r * (0.4 + p * 0.8), 0, TAU); ctx.stroke();
580:       ctx.globalAlpha = a * 0.4;
581:       ctx.beginPath(); ctx.arc(r.x, r.y, r.r * (0.15 + p * 0.45), 0, TAU); ctx.stroke();
582:       for (let i = 0; i < 6; i++) {
583:         const ang = i / 6 * TAU + p * 2;
584:         ctx.beginPath();
585:         ctx.moveTo(r.x + Math.cos(ang) * r.r * 0.3, r.y + Math.sin(ang) * r.r * 0.3);
586:         ctx.lineTo(r.x + Math.cos(ang) * r.r * (0.45 + p * 0.7), r.y + Math.sin(ang) * r.r * (0.45 + p * 0.7));
587:         ctx.stroke();
588:       }
589:     }
590:     ctx.restore();
591:   }
592: 
593:   function drawTelegraphs(ctx, t) {
594:     if (!state.telegraphs.length) return;
595:     for (const tg of state.telegraphs) {
596:       const p = clamp(1 - tg.life / tg.max, 0, 1);
597:       ctx.save();
598:       ctx.translate(tg.x, tg.y);
599:       ctx.globalAlpha = 0.1 + p * 0.16;
600:       ctx.fillStyle = tg.color;
601:       ctx.beginPath(); ctx.arc(0, 0, tg.r, 0, TAU); ctx.fill();
602:       ctx.globalAlpha = 0.42 + Math.sin(t * 16) * 0.08;
603:       ctx.strokeStyle = tg.color;
604:       ctx.lineWidth = 1.2;
605:       ctx.setLineDash([4, 8]);
606:       ctx.beginPath(); ctx.arc(0, 0, tg.r, 0, TAU); ctx.stroke();
607:       ctx.setLineDash([]);
608:       ctx.globalAlpha = 0.55;
609:       ctx.beginPath(); ctx.arc(0, 0, tg.r * p, 0, TAU); ctx.stroke();
610:       ctx.beginPath(); ctx.arc(0, 0, tg.r * 0.22, 0, TAU); ctx.stroke();
611:       ctx.globalAlpha = 0.3;
612:       for (let i = 0; i < 4; i++) {
613:         const a = i / 4 * TAU + Math.PI / 4;
614:         ctx.beginPath();
615:         ctx.moveTo(Math.cos(a) * tg.r * 0.3, Math.sin(a) * tg.r * 0.3);
616:         ctx.lineTo(Math.cos(a) * tg.r * 0.9, Math.sin(a) * tg.r * 0.9);
617:         ctx.stroke();
618:       }
619:       ctx.restore();
620:     }
621:   }
622: 
623:   function drawSlashes(ctx) {
624:     if (!state.slashes || !state.slashes.length) return;
625:     ctx.save();
626:     ctx.globalCompositeOperation = 'lighter';
627:     for (const s of state.slashes) {
628:       const p = s.life / s.max;
629:       ctx.save();
630:       ctx.translate(s.x, s.y);
631:       ctx.rotate(s.angle);
632:       ctx.globalAlpha = p * 0.85;
633:       ctx.strokeStyle = s.color;
634:       ctx.lineWidth = s.boss ? 10 : 6;
635:       ctx.lineCap = 'round';
636:       ctx.beginPath(); ctx.arc(0, 0, s.r, -0.62, 0.62); ctx.stroke();
637:       ctx.globalAlpha = p * 0.32;
638:       ctx.lineWidth = s.boss ? 22 : 13;
639:       ctx.beginPath(); ctx.arc(0, 0, s.r, -0.55, 0.55); ctx.stroke();
640:       ctx.restore();
641:     }
642:     ctx.restore();
643:   }
644: 
645:   function drawPickups(ctx, t) {
646:     if (!state.pickups.length) return;
647:     ctx.save();
648:     ctx.globalCompositeOperation = 'lighter';
649:     for (const p of state.pickups) {
650:       const bob = Math.sin(t * 4 + p.phase) * 3;
651:       const glow = 0.6 + Math.sin(t * 7 + p.phase) * 0.2;
652:       const fade = p.life < 2 ? p.life / 2 : 1;
653:       ctx.globalAlpha = fade * glow;
654:       const grad = ctx.createRadialGradient(p.x, p.y + bob, 0, p.x, p.y + bob, p.size * 4.5);
655:       grad.addColorStop(0, p.big ? 'rgba(255,236,180,1)' : 'rgba(216,186,255,1)');
656:       grad.addColorStop(0.25, p.big ? 'rgba(255,202,108,.55)' : 'rgba(148,96,255,.4)');
657:       grad.addColorStop(1, 'rgba(90,60,180,0)');
658:       ctx.fillStyle = grad;
659:       ctx.beginPath(); ctx.arc(p.x, p.y + bob, p.size * 4.5, 0, TAU); ctx.fill();
660:       ctx.fillStyle = p.big ? '#fff0c7' : '#f0e4ff';
661:       ctx.beginPath(); ctx.arc(p.x, p.y + bob, p.size, 0, TAU); ctx.fill();
662:       ctx.globalAlpha = fade * 0.45;
663:       ctx.strokeStyle = p.big ? '#ffd98c' : '#ac85ff';
664:       ctx.lineWidth = 0.8;
665:       ctx.beginPath(); ctx.arc(p.x, p.y + bob, p.size * 2.2, 0, TAU); ctx.stroke();
666:     }
667:     ctx.restore();
668:   }
669: 
670:   function drawProjectiles(ctx, t) {
671:     if (!state.projectiles.length) return;
672:     for (const p of state.projectiles) {
673:       ctx.save();
674:       if (p.kind === 'arrow') {
675:         ctx.translate(p.x, p.y);
676:         ctx.rotate(p.angle);
677:         ctx.strokeStyle = '#e0dfc4';
678:         ctx.lineWidth = 1.6;
679:         ctx.beginPath(); ctx.moveTo(-8, 0); ctx.lineTo(9, 0); ctx.stroke();
680:         ctx.fillStyle = '#d8e4b0';
681:         ctx.beginPath(); ctx.moveTo(9, 0); ctx.lineTo(5, -2.2); ctx.lineTo(5, 2.2); ctx.closePath(); ctx.fill();
682:         ctx.strokeStyle = 'rgba(216,228,176,.55)';
683:         ctx.lineWidth = 0.8;
684:         ctx.beginPath(); ctx.moveTo(-8, 0); ctx.lineTo(-11, -3); ctx.moveTo(-8, 0); ctx.lineTo(-11, 3); ctx.stroke();
685:       } else {
686:         ctx.globalCompositeOperation = 'lighter';
687:         const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 4);
688:         grad.addColorStop(0, '#fff6d9');
689:         grad.addColorStop(0.3, p.color);
690:         grad.addColorStop(1, 'rgba(255,120,70,0)');
691:         ctx.fillStyle = grad;
692:         ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 4, 0, TAU); ctx.fill();
693:         ctx.fillStyle = p.color;
694:         ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, TAU); ctx.fill();
695:       }
696:       ctx.restore();
697:     }
698:   }
