700:   function drawParticles(ctx) {
701:     if (!state.particles.length) return;
702:     // Additive glows first
703:     ctx.save();
704:     ctx.globalCompositeOperation = 'lighter';
705:     for (const p of state.particles) {
706:       if (!p.glow) continue;
707:       ctx.globalAlpha = clamp(p.life / p.max, 0, 1) * 0.85;
708:       ctx.fillStyle = p.color;
709:       ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, TAU); ctx.fill();
710:     }
711:     ctx.restore();
712: 
713:     ctx.save();
714:     for (const p of state.particles) {
715:       if (p.glow) continue;
716:       ctx.globalAlpha = clamp(p.life / p.max, 0, 1) * 0.9;
717:       ctx.fillStyle = p.color;
718:       if (p.line) {
719:         ctx.strokeStyle = p.color;
720:         ctx.lineWidth = p.size;
721:         ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x - p.vx * 0.04, p.y - p.vy * 0.04); ctx.stroke();
722:       } else {
723:         ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, TAU); ctx.fill();
724:       }
725:     }
726:     ctx.restore();
727:   }
