729:   function drawTexts(ctx) {
730:     if (!state.texts.length) return;
731:     ctx.save();
732:     ctx.textAlign = 'center';
733:     for (const t of state.texts) {
734:       const p = clamp(t.life / t.max, 0, 1);
735:       ctx.globalAlpha = p;
736:       ctx.font = `700 ${t.size}px ${FONT_UI}`;
737:       ctx.fillStyle = t.color;
738:       ctx.shadowColor = 'rgba(0,0,0,.9)';
