745:   function drawSurges(ctx) {
746:     if (!state.surges.length) return;
747:     ctx.save();
748:     ctx.globalCompositeOperation = 'lighter';
749:     for (const s of state.surges) {
750:       const p = 1 - s.life / s.maxLife;
751:       ctx.globalAlpha = (1 - p) * 0.8;
752:       ctx.strokeStyle = s.color || '#ff4f6b';
753:       ctx.lineWidth = 2 + (1 - p) * 3;
754:       ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, TAU); ctx.stroke();
755:       if (!s.thin) {
756:         ctx.globalAlpha = (1 - p) * 0.24;
757:         ctx.lineWidth = 10;
758:         ctx.beginPath(); ctx.arc(s.x, s.y, s.r * 0.91, 0, TAU); ctx.stroke();
759:         for (let i = 0; i < 10; i++) {
760:           const a = i / 10 * TAU + p * 0.8;
761:           ctx.globalAlpha = (1 - p) * 0.3;
762:           ctx.lineWidth = 1;
763:           ctx.beginPath();
764:           ctx.moveTo(s.x + Math.cos(a) * s.r * 0.55, s.y + Math.sin(a) * s.r * 0.55);
765:           ctx.lineTo(s.x + Math.cos(a) * s.r * 1.08, s.y + Math.sin(a) * s.r * 1.08);
766:           ctx.stroke();
767:         }
768:       }
769:     }
770:     ctx.restore();
771:   }
