773:   function drawHorde(ctx, t) {
774:     const h = state.horde;
775:     if (!h) return;
776: 
777:     // Dark ground stain beneath the swarm
778:     ctx.save();
779:     ctx.globalAlpha = 0.5;
780:     const gg = ctx.createRadialGradient(h.x, h.y + 4, 0, h.x, h.y + 4, 90);
781:     gg.addColorStop(0, 'rgba(52,8,24,.46)');
782:     gg.addColorStop(0.65, 'rgba(24,4,14,.18)');
783:     gg.addColorStop(1, 'rgba(0,0,0,0)');
784:     ctx.fillStyle = gg;
785:     ctx.beginPath(); ctx.arc(h.x, h.y + 4, 90, 0, TAU); ctx.fill();
786:     ctx.restore();
787: 
788:     // Heart glow
789:     ctx.save();
790:     ctx.globalCompositeOperation = 'lighter';
791:     const beat = 1 + Math.sin(t * 5.2) * 0.12 + h.pulse * 0.55;
792:     const grad = ctx.createRadialGradient(h.x, h.y, 0, h.x, h.y, 56 * beat);
793:     grad.addColorStop(0, 'rgba(255,72,102,.42)');
794:     grad.addColorStop(0.3, 'rgba(199,31,68,.17)');
795:     grad.addColorStop(1, 'rgba(100,10,40,0)');
796:     ctx.fillStyle = grad;
797:     ctx.beginPath(); ctx.arc(h.x, h.y, 56 * beat, 0, TAU); ctx.fill();
798:     ctx.globalAlpha = 0.8;
799:     ctx.strokeStyle = 'rgba(255,104,127,.42)';
800:     ctx.lineWidth = 1;
801:     ctx.beginPath(); ctx.arc(h.x, h.y, 14 + Math.sin(t * 5.2) * 1.3, 0, TAU); ctx.stroke();
802:     for (let i = 0; i < 7; i++) {
803:       const a = i / 7 * TAU + t * 0.8;
804:       const r1 = 18, r2 = 24 + Math.sin(t * 3 + i) * 3;
805:       ctx.globalAlpha = 0.5;
806:       ctx.beginPath();
807:       ctx.moveTo(h.x + Math.cos(a) * r1, h.y + Math.sin(a) * r1);
808:       ctx.lineTo(h.x + Math.cos(a) * r2, h.y + Math.sin(a) * r2);
809:       ctx.stroke();
810:     }
811:     ctx.restore();
812: 
813:     // The heart itself
814:     ctx.save();
815:     ctx.translate(h.x, h.y + Math.sin(t * 3) * 1.2);
816:     const pulse = 1 + Math.sin(t * 5.2) * 0.08 + h.pulse * 0.24;
817:     ctx.scale(pulse, pulse);
818:     ctx.fillStyle = '#170912';
819:     ctx.strokeStyle = 'rgba(255,91,116,.75)';
820:     ctx.lineWidth = 1.2;
821:     ctx.beginPath();
822:     ctx.moveTo(0, 10);
823:     ctx.bezierCurveTo(-12, 1, -9, -9, -3.5, -7);
824:     ctx.bezierCurveTo(-1.5, -6, 0, -3.5, 0, -3.5);
825:     ctx.bezierCurveTo(0, -3.5, 1.5, -6, 3.5, -7);
826:     ctx.bezierCurveTo(9, -9, 12, 1, 0, 10);
827:     ctx.closePath();
828:     ctx.fill(); ctx.stroke();
829:     ctx.strokeStyle = 'rgba(255,178,150,.36)';
830:     ctx.lineWidth = 0.7;
831:     ctx.beginPath(); ctx.moveTo(-5, -3); ctx.lineTo(-2, 0); ctx.lineTo(-4, 3); ctx.stroke();
832:     ctx.restore();
833: 
834:     for (const b of h.bats) H.drawBat(ctx, b, t);
835:   }
