890:   function drawCampfire(ctx, x, y, s, t) {
891:     // warm ground light
892:     const glow = ctx.createRadialGradient(x, y, 0, x, y, 210 * s);
893:     glow.addColorStop(0, 'rgba(255,176,83,.35)');
894:     glow.addColorStop(0.3, 'rgba(230,105,50,.12)');
895:     glow.addColorStop(1, 'rgba(140,40,30,0)');
896:     ctx.fillStyle = glow;
897:     ctx.beginPath(); ctx.arc(x, y, 210 * s, 0, TAU); ctx.fill();
898: 
899:     // stone ring
900:     ctx.save();
901:     ctx.translate(x, y);
902:     for (let i = 0; i < 11; i++) {
903:       const a = i / 11 * TAU + 0.15;
904:       const rx = Math.cos(a) * 31 * s, ry = Math.sin(a) * 18 * s;
905:       ctx.fillStyle = i % 2 ? '#1d1820' : '#141018';
906:       ctx.beginPath(); ctx.ellipse(rx, ry, 6 * s, 4.5 * s, a, 0, TAU); ctx.fill();
907:       ctx.strokeStyle = 'rgba(255,187,104,.08)'; ctx.stroke();
908:     }
909:     ctx.strokeStyle = '#2a1a1e'; ctx.lineWidth = 4 * s; ctx.lineCap = 'round';
910:     ctx.beginPath(); ctx.moveTo(-16 * s, -8 * s); ctx.lineTo(16 * s, 9 * s); ctx.moveTo(16 * s, -8 * s); ctx.lineTo(-16 * s, 9 * s); ctx.stroke();
911:     ctx.restore();
912: 
913:     // flames
914:     ctx.save();
915:     ctx.translate(x, y);
916:     ctx.globalCompositeOperation = 'lighter';
917:     const flick = Math.sin(t * 9.3) * 3 + Math.sin(t * 14.1) * 1.5;
918:     const layers = [
919:       [28, 66 + flick, 'rgba(255,93,45,.52)'],
920:       [19, 49 + flick * 0.7, 'rgba(255,169,74,.68)'],
921:       [10, 31 + flick * 0.4, 'rgba(255,236,178,.9)']
922:     ];
923:     for (const [ww, hh, col] of layers) {
924:       ctx.fillStyle = col;
925:       ctx.beginPath();
926:       ctx.moveTo(-ww * s, 4 * s);
927:       ctx.bezierCurveTo(-ww * 1.2 * s, -hh * 0.25 * s, -6 * s, -hh * 0.72 * s, -2 * s + flick, -hh * s);
928:       ctx.bezierCurveTo(8 * s, -hh * 0.62 * s, ww * 1.2 * s, -hh * 0.22 * s, ww * s, 4 * s);
929:       ctx.closePath();
930:       ctx.fill();
931:     }
932:     // embers
933:     for (let i = 0; i < 9; i++) {
934:       const seed = i * 17.17;
935:       const life = ((t * (0.18 + i * 0.013) + seed) % 1);
936:       const ex = Math.sin(seed + t * 1.5) * 24 * s * life;
937:       const ey = -life * 120 * s;
938:       ctx.globalAlpha = (1 - life) * 0.7;
939:       ctx.fillStyle = i % 3 ? '#ffca78' : '#ff7a49';
940:       ctx.beginPath(); ctx.arc(ex, ey, (1.2 + (i % 2)) * s * (1 - life * 0.5), 0, TAU); ctx.fill();
941:     }
942:     ctx.restore();
943:   }
944: 
945:   function drawAttract(ctx, t) {
