:root {
  --ink: #07060d;
  --ink-2: #0d0a16;
  --panel: rgba(13, 10, 21, 0.82);
  --bone: #f3ead9;
  --bone-dim: #bbae9b;
  --blood: #e3425f;
  --blood-hot: #ff5d78;
  --blood-deep: #8f1734;
  --gold: #d8ad6a;
  --gold-pale: #f6dca7;
  --mist: #8d93b2;
  --line: rgba(226, 190, 149, 0.18);
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, "Iowan Old Style", "Times New Roman", serif;
  --sans: "Avenir Next", Avenir, "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

button { font: inherit; color: inherit; }
kbd {
  display: inline-block;
  min-width: 22px;
  padding: 2px 5px 1px;
  border: 1px solid rgba(243, 234, 217, 0.25);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--bone-dim);
  font-family: var(--sans);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-align: center;
  box-shadow: inset 0 -1px 0 rgba(255,255,255,.06);
}
.hidden { display: none !important; }

#app {
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 100%;
  height: 100svh;
  overflow: hidden;
  background: var(--ink);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

.grain {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  opacity: 0.16;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.42'/%3E%3C/svg%3E");
  background-size: 240px 240px;
}
.vignette {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 47%, transparent 42%, rgba(4, 3, 8, 0.32) 80%, rgba(3, 2, 7, 0.78) 120%),
    linear-gradient(to bottom, rgba(4, 3, 8, 0.32), transparent 16%, transparent 79%, rgba(4, 3, 8, 0.55));
}
#low-horde {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(117, 0, 24, 0.4) 90%, rgba(80, 0, 16, 0.66));
  transition: opacity .35s ease;
  animation: lowPulse 1.1s ease-in-out infinite alternate;
}
#low-horde.on { opacity: 1; }
@keyframes lowPulse { from { filter: brightness(.85); } to { filter: brightness(1.3); } }

/* ---------- Shared type ---------- */
.eyebrow {
  display: block;
  font-family: var(--sans);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .26em;
  color: rgba(243, 234, 217, .55);
  text-transform: uppercase;
}
.level-kicker {
  color: var(--blood);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .36em;
  text-transform: uppercase;
}

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: max(18px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(20px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  animation: hudIn .7s ease both;
}
