.horde-number b { font-weight: 600; }
.meter { height: 3px; margin-top: 7px; overflow: hidden; background: rgba(255,255,255,.09); border-radius: 3px; }
.meter i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, var(--blood-deep), var(--blood-hot)); box-shadow: 0 0 10px var(--blood); transition: width .2s ease; }

.timer-panel { text-align: center; padding-top: 5px; min-width: 138px; }
.timer-panel .eyebrow { color: rgba(216, 173, 106, .78); letter-spacing: .32em; }
#timer {
  font-family: var(--serif);
  font-size: 36px;
  line-height: .95;
  margin-top: 3px;
  letter-spacing: .03em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 22px rgba(0,0,0,.75);
}
.timer-sub { display: block; font-size: 7px; letter-spacing: .31em; color: rgba(243,234,217,.38); margin-top: 3px; }
.timer-panel.urgent #timer { color: var(--blood-hot); animation: urgent 1s ease-in-out infinite alternate; }
@keyframes urgent { to { text-shadow: 0 0 26px rgba(255, 72, 100, .75); } }

.score-panel {
