.icon-btn.muted .sound-on { display: none; }
.icon-btn.muted .sound-off { display: block; }
.kill-stat { min-width: 76px; padding: 0 7px 0 12px; border-left: 1px solid rgba(255,255,255,.08); text-align: right; }
.kill-stat strong { display: block; font-family: var(--serif); font-size: 22px; line-height: 1; color: var(--gold-pale); font-variant-numeric: tabular-nums; }

.hud-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
