.xp-track { height: 4px; background: rgba(255,255,255,.08); overflow: hidden; border-radius: 3px; box-shadow: 0 0 0 1px rgba(255,255,255,.03); }
.xp-track i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #7c4fbd, #cda2ff); box-shadow: 0 0 12px rgba(161, 111, 255, .62); transition: width .3s ease; }
.objective { display: flex; align-items: center; gap: 8px; margin-top: 9px; font-size: 10px; letter-spacing: .04em; color: rgba(243,234,217,.52); }
.obj-dot { width: 4px; height: 4px; transform: rotate(45deg); background: var(--blood); box-shadow: 0 0 8px var(--blood); flex: 0 0 auto; }

.ability-wrap { position: relative; pointer-events: none; text-align: right; }
.ability {
  position: relative;
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 180px;
  padding: 8px 14px 8px 9px;
  color: var(--bone);
  background: rgba(13, 10, 21, .82);
  border: 1px solid rgba(227,66,95,.35);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  cursor: pointer;
  transition: .2s ease;
  backdrop-filter: blur(10px);
}
.ability:hover { border-color: rgba(255,93,120,.7); background: rgba(28,10,20,.92); }
.ability-ring {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(227,66,95,.55);
  background: radial-gradient(circle, rgba(227,66,95,.26), rgba(227,66,95,.02) 68%);
  color: var(--blood-hot);
  filter: drop-shadow(0 0 7px rgba(227,66,95,.45));
}
.ability-ring svg { width: 23px; height: 23px; }
.ability-copy { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; }
.ability-copy b { font-size: 9px; letter-spacing: .21em; }
.ability-copy small { font-size: 7px; letter-spacing: .2em; color: rgba(243,234,217,.38); }
.ability-cd { margin-top: 5px; font-size: 7px; font-weight: 800; letter-spacing: .27em; color: var(--blood-hot); }
.ability.cooling .ability-ring { color: rgba(243,234,217,.3); border-color: rgba(255,255,255,.14); background: rgba(255,255,255,.03); filter: none; }
.ability.cooling .ability-cd { color: rgba(243,234,217,.38); }
.mobile-hint { display: none; }
#joystick {
  display: none;
  position: absolute;
  z-index: 12;
  width: 104px;
  height: 104px;
  margin: -52px 0 0 -52px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(227,66,95,.1), rgba(7,6,13,.3));
  pointer-events: none;
  backdrop-filter: blur(3px);
}
#joystick span {
  position: absolute;
  left: 50%; top: 50%;
  width: 38px; height: 38px;
  margin: -19px;
  border-radius: 50%;
  border: 1px solid rgba(255,93,120,.7);
  background: radial-gradient(circle, rgba(227,66,95,.65), rgba(100,18,41,.5));
  box-shadow: 0 0 20px rgba(227,66,95,.35);
}
#joystick.on { display: block; }

/* ---------- Title ---------- */
.screen { position: absolute; inset: 0; z-index: 20; }
.title-screen {
  display: flex;
  align-items: center;
  padding: clamp(22px, 5vw, 74px);
  padding-top: max(26px, env(safe-area-inset-top));
  padding-bottom: max(38px, env(safe-area-inset-bottom));
  overflow: hidden;
}
.title-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(5,4,10,.97) 0%, rgba(5,4,10,.88) 29%, rgba(5,4,10,.56) 49%, rgba(5,4,10,.1) 76%, rgba(5,4,10,.2) 100%),
    linear-gradient(0deg, rgba(5,4,10,.78), transparent 30%, transparent 72%, rgba(5,4,10,.45));
}
.title-content {
  position: relative;
  z-index: 2;
  width: min(650px, 55vw);
  animation: titleIn 1.1s cubic-bezier(.2,.8,.2,1) both .15s;
}
@keyframes titleIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.title-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(100%, 470px);
  color: rgba(216,173,106,.75);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .4em;
  white-space: nowrap;
}
.title-kicker span { width: 28px; height: 1px; background: linear-gradient(90deg, transparent, rgba(216,173,106,.5)); }
.title-kicker span:last-child { background: linear-gradient(90deg, rgba(216,173,106,.5), transparent); }
.game-title {
  position: relative;
  margin: 6px 0 0 -8px;
  font-family: var(--serif);
  font-size: clamp(100px, 13.2vw, 178px);
  line-height: .76;
  letter-spacing: -.045em;
  font-weight: 700;
  white-space: nowrap;
  color: #f7e7cc;
  background: linear-gradient(180deg, #fff7e6 0%, #e7c9a0 43%, #b95b62 68%, #7e1b34 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 5px 0 rgba(26, 6, 14, .72)) drop-shadow(0 12px 30px rgba(155, 24, 54, .22));
}
.game-title > span:not(.title-drip) {
  display: inline-block;
  background: inherit;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.title-h { transform: rotate(-1deg); }
.title-o { transform: translateY(2px) rotate(.6deg); }
.title-r { transform: rotate(-.7deg); }
.title-d { transform: translateY(1px) rotate(.4deg); }
.title-e { transform: rotate(-.4deg); }
.title-drip {
  position: absolute;
  top: 78%;
  width: 3px;
  border-radius: 0 0 50% 50%;
  background: linear-gradient(to bottom, #8e1d38, #520c20);
  opacity: .8;
}
.drip-a { left: 14%; height: 22px; }
.drip-b { left: 57%; height: 38px; width: 4px; top: 80%; }
.drip-c { left: 82%; height: 14px; }
.title-rule {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(100%, 510px);
  margin: 10px 0 20px;
  color: rgba(243,234,217,.45);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .34em;
}
.title-rule i { height: 1px; flex: 1; background: linear-gradient(90deg, rgba(216,173,106,.34), transparent); }
.title-rule i:last-child { background: linear-gradient(270deg, rgba(216,173,106,.34), transparent); }
.title-hook {
  margin: 0 0 14px;
  font-family: var(--serif);
  font-size: clamp(19px, 1.8vw, 27px);
  line-height: 1.32;
  letter-spacing: .005em;
  color: rgba(243,234,217,.86);
}
.title-hook em { color: var(--blood-hot); font-style: italic; text-shadow: 0 0 24px rgba(227,66,95,.3); }
.title-desc {
  margin: 0 0 24px;
  max-width: 500px;
  font-size: clamp(11px, .92vw, 14px);
  line-height: 1.72;
  color: rgba(243,234,217,.44);
}
.title-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 13px; }
.primary-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 13px;
  width: min(368px, 100%);
  min-height: 64px;
  padding: 10px 14px;
  border: 1px solid rgba(255,117,138,.55);
  background:
    linear-gradient(115deg, rgba(255,255,255,.1), transparent 30%),
    linear-gradient(90deg, #79162e, #a32241 54%, #6f1028);
  color: #fff0dc;
  cursor: pointer;
  clip-path: polygon(13px 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%, 0 13px);
  box-shadow: 0 16px 40px rgba(87, 7, 28, .34), inset 0 1px 0 rgba(255,255,255,.15);
  transition: transform .2s ease, filter .2s ease, box-shadow .2s ease;
  text-align: left;
}
.primary-btn::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(255,232,203,.1);
  pointer-events: none;
}
.primary-btn:hover { transform: translateY(-2px); filter: brightness(1.13); box-shadow: 0 20px 50px rgba(138, 15, 46, .48), inset 0 1px 0 rgba(255,255,255,.18); }
.primary-btn:active { transform: translateY(0); }
.btn-icon { width: 36px; height: 36px; flex: 0 0 auto; color: #ffd9c0; filter: drop-shadow(0 0 12px rgba(255,168,160,.35)); }
.btn-icon svg { width: 100%; height: 100%; }
.primary-btn b { display: block; font-size: 11px; font-weight: 800; letter-spacing: .23em; }
.primary-btn small { display: block; margin-top: 3px; font-size: 7px; letter-spacing: .22em; color: rgba(255,232,203,.52); }
.btn-arrow { margin-left: auto; font-family: var(--serif); font-size: 22px; color: rgba(255,232,203,.55); transition: transform .2s ease; }
.primary-btn:hover .btn-arrow { transform: translateX(4px); color: #fff; }
.title-meta { display: flex; gap: 17px; flex-wrap: wrap; align-items: center; color: rgba(243,234,217,.38); font-size: 8px; letter-spacing: .13em; text-transform: uppercase; }
.title-meta span { display: flex; align-items: center; gap: 6px; }
.title-meta kbd { font-size: 7px; }
.title-record { margin-top: 19px; padding-left: 10px; border-left: 1px solid rgba(227,66,95,.45); font-size: 8px; font-weight: 700; letter-spacing: .18em; color: rgba(216,173,106,.52); text-transform: uppercase; }

.title-side {
  position: absolute;
  z-index: 2;
  right: clamp(24px, 4vw, 70px);
  top: 50%;
  transform: translateY(-46%);
  text-align: right;
  color: rgba(243,234,217,.28);
  animation: titleIn 1.2s ease both .6s;
}
.moon-mark { width: 66px; height: 66px; margin: 0 0 20px auto; position: relative; border: 1px solid rgba(216,173,106,.28); border-radius: 50%; }
.moon-mark::before { content: ""; position: absolute; inset: 10px; border-radius: 50%; background: radial-gradient(circle at 38% 36%, #f6dca7, #b27645 58%, #4f2834 75%); box-shadow: 0 0 38px rgba(216,173,106,.25); }
.moon-mark::after { content: ""; position: absolute; inset: 3px; border: 1px dashed rgba(216,173,106,.24); border-radius: 50%; animation: slowSpin 28s linear infinite; }
.moon-mark span { position: absolute; inset: 18px -4px -4px 18px; background: #07060d; border-radius: 50%; z-index: 1; }

.moon-mark span { position: absolute; inset: 18px -4px -4px 18px; background: #07060d; border-radius: 50%; z-index: 1; }
@keyframes slowSpin { to { transform: rotate(360deg); } }
.title-side p { margin: 0; font-family: var(--serif); font-size: 10px; line-height: 1.65; letter-spacing: .19em; }
.title-side small { display: block; margin-top: 6px; font-size: 6px; letter-spacing: .27em; color: rgba(243,234,217,.22); }
.title-footer {
  position: absolute;
  z-index: 3;
  left: clamp(24px, 5vw, 74px);
  right: clamp(24px, 5vw, 74px);
  bottom: max(15px, env(safe-area-inset-bottom));
  display: flex;
  align-items: center;
  gap: 20px;
  color: rgba(243,234,217,.23);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .24em;
}
.footer-bats { flex: 1; overflow: hidden; white-space: nowrap; color: rgba(227,66,95,.4); letter-spacing: .7em; }
.text-btn { border: 0; background: none; color: rgba(243,234,217,.35); font-size: 7px; letter-spacing: .24em; cursor: pointer; padding: 4px 0; }
.text-btn:hover { color: var(--bone); }

/* ---------- Overlay screens ---------- */
.overlay-screen {
  display: grid;
  place-items: center;
  padding: 22px;
  background: radial-gradient(ellipse at center, rgba(10,6,18,.62), rgba(3,2,7,.89) 74%);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: overlayIn .3s ease both;
  overflow-y: auto;
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }
.modal-glow { position: absolute; width: 760px; height: 520px; background: radial-gradient(ellipse, rgba(145,20,53,.22), transparent 65%); pointer-events: none; }
.level-panel { position: relative; z-index: 1; width: min(940px, 95vw); text-align: center; }
.level-panel h2, .small-panel h2, .end-wrap h2 {
  margin: 8px 0 4px;
  font-family: var(--serif);
  font-size: clamp(32px, 4vw, 54px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -.02em;
  color: #f7ead6;
}
.level-sub, .small-copy { margin: 0 0 25px; color: rgba(243,234,217,.4); font-size: 11px; letter-spacing: .04em; }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; width: 100%; }
.card {
  position: relative;
  min-height: 258px;
  padding: 27px 23px 20px;
  border: 1px solid rgba(243,234,217,.14);
  background:
    linear-gradient(145deg, rgba(255,255,255,.045), transparent 44%),
    rgba(12,9,19,.84);
  color: var(--bone);
  cursor: pointer;
  text-align: left;
  overflow: hidden;
  clip-path: polygon(15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%, 0 15px);
  transition: transform .2s ease, border-color .2s ease, background .2s ease;
  animation: cardIn .45s cubic-bezier(.2,.8,.2,1) both;
}
.card:nth-child(2) { animation-delay: .07s; }
.card:nth-child(3) { animation-delay: .14s; }
@keyframes cardIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.card::before { content: ""; position: absolute; inset: 5px; border: 1px solid rgba(255,255,255,.035); pointer-events: none; }
.card::after { content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: 100%; background: linear-gradient(90deg, transparent, var(--blood), transparent); opacity: 0; transition: opacity .2s ease; }
.card:hover { transform: translateY(-4px); border-color: rgba(227,66,95,.55); background: linear-gradient(145deg, rgba(227,66,95,.09), transparent 48%), rgba(17,10,22,.94); }
.card:hover::after { opacity: 1; }
.card-key { position: absolute; top: 12px; right: 14px; font-size: 8px; letter-spacing: .16em; color: rgba(243,234,217,.28); }
.card-icon { width: 54px; height: 54px; display: grid; place-items: center; color: var(--blood-hot); border: 1px solid rgba(227,66,95,.26); background: radial-gradient(circle at 45% 40%, rgba(227,66,95,.17), transparent 68%); margin-bottom: 21px; transform: rotate(45deg); }
.card-icon svg { width: 30px; height: 30px; transform: rotate(-45deg); }
.card-tier { margin-bottom: 6px; font-size: 7px; font-weight: 800; letter-spacing: .28em; color: var(--gold); }
.card h3 { margin: 0 0 9px; font-family: var(--serif); font-size: 24px; font-weight: 500; letter-spacing: -.01em; }
.card p { margin: 0; color: rgba(243,234,217,.45); font-size: 11px; line-height: 1.65; }
.card-stat { position: absolute; left: 23px; bottom: 20px; font-size: 8px; font-weight: 800; letter-spacing: .15em; color: rgba(246,220,167,.7); }
.level-foot { display: flex; justify-content: space-between; margin-top: 18px; color: rgba(243,234,217,.28); font-size: 8px; letter-spacing: .18em; text-transform: uppercase; }

.small-panel {
  position: relative;
  width: min(470px, 92vw);
  padding: 36px 38px 30px;
  background: linear-gradient(145deg, rgba(255,255,255,.04), transparent 46%), rgba(11,8,18,.92);
  border: 1px solid var(--line);
  text-align: center;
  clip-path: polygon(18px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%, 0 18px);
}
.small-panel h2 { font-size: 46px; }
.pause-actions { display: flex; flex-direction: column; gap: 9px; margin-top: 24px; }
.primary-btn.compact { width: 100%; min-height: 55px; justify-content: center; text-align: center; display: block; padding: 10px; }
.primary-btn.compact b { font-size: 10px; }
.ghost-btn {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid rgba(243,234,217,.14);
  background: rgba(255,255,255,.025);
  color: rgba(243,234,217,.5);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .22em;
  cursor: pointer;
  transition: .2s ease;
}
.ghost-btn:hover { border-color: rgba(243,234,217,.34); color: var(--bone); background: rgba(255,255,255,.05); }
.pause-tip { margin-top: 20px; padding-top: 16px; border-top: 1px solid rgba(255,255,255,.06); font-size: 8px; line-height: 1.6; letter-spacing: .05em; color: rgba(243,234,217,.28); }
.pause-tip span { color: rgba(243,234,217,.47); }

/* ---------- End ---------- */
.end-wrap { width: min(590px, 92vw); text-align: center; position: relative; }
.end-mark { width: 70px; height: 70px; margin: 0 auto 15px; color: var(--gold); filter: drop-shadow(0 0 22px rgba(216,173,106,.25)); }
.end-mark svg { width: 100%; height: 100%; }
.end-wrap h2 { font-size: clamp(40px, 5.2vw, 64px); }
.end-copy { max-width: 440px; margin: 9px auto 25px; font-size: 11px; line-height: 1.7; color: rgba(243,234,217,.42); }
.end-stats { display: grid; grid-template-columns: repeat(3, 1fr); border-top: 1px solid rgba(243,234,217,.12); border-bottom: 1px solid rgba(243,234,217,.12); padding: 17px 0; margin-bottom: 22px; }
.end-stats div { padding: 0 12px; border-right: 1px solid rgba(243,234,217,.08); }
.end-stats div:last-child { border-right: 0; }
.end-stats span { display: block; font-size: 7px; font-weight: 800; letter-spacing: .2em; color: rgba(243,234,217,.35); }
.end-stats strong { display: block; margin-top: 5px; font-family: var(--serif); font-size: 25px; font-weight: 500; color: var(--gold-pale); }
.new-best { margin: -6px 0 18px; color: var(--gold); font-size: 8px; letter-spacing: .34em; font-weight: 800; animation: bestPulse 1.6s ease-in-out infinite alternate; }
@keyframes bestPulse { to { filter: brightness(1.5); text-shadow: 0 0 18px rgba(216,173,106,.4); } }
.end-actions { display: flex; flex-direction: column; align-items: center; gap: 9px; }
.end-actions .ghost-btn { width: min(368px, 100%); }
.end-record { margin-top: 18px; font-size: 7px; letter-spacing: .19em; color: rgba(243,234,217,.26); }
.end-wrap.victory .end-mark { color: var(--blood-hot); filter: drop-shadow(0 0 28px rgba(227,66,95,.5)); }
.end-wrap.victory .level-kicker { color: var(--gold); }
.end-wrap.victory h2 { color: var(--gold-pale); text-shadow: 0 0 34px rgba(216,173,106,.2); }

/* ---------- Banner / toast ---------- */
.banner {
  position: absolute;
  z-index: 15;
  top: 21%;
  left: 50%;
  transform: translate(-50%, -8px);
  text-align: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity .35s ease, transform .5s cubic-bezier(.2,.8,.2,1);
  text-shadow: 0 4px 30px #000;
  white-space: nowrap;
}
.banner.show { opacity: 1; transform: translate(-50%, 0); }
.banner small { display: block; margin-bottom: 5px; color: var(--blood); font-size: 7px; font-weight: 800; letter-spacing: .44em; }
.banner strong { display: block; font-family: var(--serif); font-size: clamp(25px, 3.2vw, 44px); font-weight: 500; letter-spacing: .04em; color: #f6e5c9; }
.banner.boss strong { color: #ffdfaa; text-shadow: 0 0 26px rgba(255,177,89,.33), 0 4px 30px #000; }
.toast {
  position: absolute;
  z-index: 16;
  left: 50%;
  bottom: 24%;
  transform: translate(-50%, 6px);
  padding: 8px 15px;
  border: 1px solid rgba(227,66,95,.3);
  background: rgba(10,7,16,.85);
  color: rgba(246,220,167,.78);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  pointer-events: none;
  opacity: 0;
  transition: .25s ease;
  backdrop-filter: blur(5px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .title-content { width: min(620px, 74vw); }
  .title-side { display: none; }
  .title-shade { background: linear-gradient(90deg, rgba(5,4,10,.97) 0%, rgba(5,4,10,.84) 44%, rgba(5,4,10,.3) 100%), linear-gradient(0deg, rgba(5,4,10,.85), transparent 38%); }
  .game-title { font-size: clamp(98px, 20vw, 158px); }
  .horde-panel { width: 205px; }
  .cards { gap: 10px; }
  .card { padding: 23px 18px 18px; min-height: 242px; }
  .card h3 { font-size: 21px; }
  .card-stat { left: 18px; }
}

@media (max-width: 640px) {
  #hud { padding: max(11px, env(safe-area-inset-top)) max(11px, env(safe-area-inset-right)) max(12px, env(safe-area-inset-bottom)) max(11px, env(safe-area-inset-left)); }
  .hud-top { gap: 7px; }
  .horde-panel { width: 148px; padding: 7px 10px 7px 7px; gap: 7px; }
  .horde-icon { width: 32px; height: 32px; }
  .horde-number { font-size: 20px; }
  .horde-number span { font-size: 8px; }
  .meter { margin-top: 4px; }
  .eyebrow { font-size: 6px; letter-spacing: .19em; }
  .timer-panel { min-width: 80px; padding-top: 2px; }
  #timer { font-size: 27px; }
  .timer-sub { font-size: 5px; }
  .score-panel { height: 48px; padding: 0 3px 0 0; }
  .score-panel::before, .score-panel::after { display: none; }
  .icon-btn { width: 30px; height: 30px; }
  .kill-stat { min-width: 48px; padding: 0 6px; }
  .kill-stat strong { font-size: 18px; }
  .kill-stat .eyebrow { font-size: 5px; }
  .xp-panel { width: 47vw; }
  .xp-head { font-size: 6px; letter-spacing: .1em; }
  .xp-head span:last-child { display: none; }
  .objective { font-size: 7px; margin-top: 6px; }
  .ability { min-width: 0; padding: 6px; background: transparent; border: 0; backdrop-filter: none; clip-path: none; }
  .ability::after { content: ""; position: absolute; inset: 0; border: 1px solid rgba(227,66,95,.5); border-radius: 50%; }
  .ability-ring { width: 58px; height: 58px; }
  .ability-copy, .ability-cd { display: none; }
  .mobile-hint { display: block; position: absolute; bottom: 92px; left: 50%; transform: translateX(-50%); font-size: 6px; letter-spacing: .25em; color: rgba(243,234,217,.3); white-space: nowrap; }

  .title-screen { align-items: flex-end; padding: 18px 20px max(40px, env(safe-area-inset-bottom)); }
  .title-content { width: 100%; }
  .title-shade { background: linear-gradient(0deg, rgba(4,3,8,.98) 0%, rgba(4,3,8,.93) 38%, rgba(4,3,8,.62) 68%, rgba(4,3,8,.16) 100%); }
  .title-kicker { font-size: 6px; letter-spacing: .24em; }
