  .title-rule { margin: 8px 0 12px; font-size: 6px; }
  .title-hook { font-size: 18px; margin-bottom: 9px; }
  .title-desc { display: none; }
  .title-actions { gap: 10px; }
  .primary-btn { min-height: 58px; }
  .title-meta { font-size: 7px; gap: 12px; }
  .hide-mobile { display: none !important; }
  .title-record { margin-top: 12px; font-size: 6px; }
  .title-footer { left: 20px; right: 20px; bottom: max(12px, env(safe-area-inset-bottom)); font-size: 6px; gap: 8px; }
  .footer-bats { display: none; }

  .level-panel h2 { font-size: 31px; }
  .level-sub { margin-bottom: 16px; font-size: 9px; }
  .cards { grid-template-columns: 1fr; gap: 8px; max-height: 58svh; overflow-y: auto; padding: 2px; }
  .card { min-height: 0; padding: 13px 15px 13px 70px; clip-path: none; }
  .card-icon { position: absolute; left: 15px; top: 15px; width: 38px; height: 38px; margin: 0; }
  .card-icon svg { width: 21px; height: 21px; }
  .card-tier { font-size: 6px; margin-bottom: 2px; }
  .card h3 { font-size: 18px; margin-bottom: 3px; }
  .card p { font-size: 9px; line-height: 1.45; }
  .card-stat { position: static; display: block; margin-top: 5px; font-size: 6px; }
  .card-key { font-size: 7px; }
  .level-foot { font-size: 6px; }
  .small-panel { padding: 26px 22px 22px; }
  .small-panel h2 { font-size: 38px; }
  .end-wrap .end-stats strong { font-size: 20px; }
  .end-copy { margin-bottom: 18px; }
}

@media (max-height: 720px) and (min-width: 641px) {
